void IioSensorInstanceInterceptorForTesting::OnTabletModeChanged(bool is_tablet_mode_on) {
  GetForwardingInterface()->OnTabletModeChanged(std::move(is_tablet_mode_on));
}
IioSensorInstanceAsyncWaiter::IioSensorInstanceAsyncWaiter(
    IioSensorInstance* proxy) : proxy_(proxy) {}

IioSensorInstanceAsyncWaiter::~IioSensorInstanceAsyncWaiter() = default;

void IioSensorInstanceAsyncWaiter::Init(
    ::mojo::PendingRemote<IioSensorHost> host_remote) {
  base::RunLoop loop;
  proxy_->Init(std::move(host_remote),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








